      details: '权杖八是权杖牌组中最"纯粹"的行动牌之一——没有人物、没有冲突、没有情感，只有运动和速度。八根权杖在空中飞行，方向一致，代表"协调的行动"。它们是从地面飞向天空的，但运动方向是向下的——暗示这些行动正在从"想法"阶段进入"落地"阶段。',
      misperceptions: '权杖八"不是"代表"事情会永远顺利"。它代表的是"当前进展非常顺利"——但就像飞行的权杖终会落地，高速的进展也终会到达一个阶段性的终点。享受这个加速度，但也要为下一个阶段做好准备。'
