      upright: '自信、温暖、魅力、领导力、热情、独立。权杖王后正位代表你是一个充满自信和魅力的人——你像太阳一样温暖他人，同时也保持着自己的独立和力量。你不仅在事业上有成就，在人际关系中也非常受欢迎。',
