      details: '权杖王后是权杖宫廷牌中的"成熟女性"——她代表火元素的成熟和稳定。她不像侍从那样好奇，也不像骑士那样冲动——她拥有的是"成熟的自信"。向日葵是她最明显的标志——它既代表她追随光明的天性，也代表她本身就是光明的来源。黑猫象征她的直觉和独立——她不需要依靠任何人。',
