    upright: '圣杯四是一种"情感饱和"的状态——你已经拥有了很多，却感到厌倦和空虚。这张牌出现在你对自己的人生感到不满、却又不知如何改变的时候。你可能会对现有的感情、工作或生活状态感到麻木，觉得一切都没有意义。但牌面上云中递来的第四个杯子提醒你：新的机会正在出现，只是你沉浸在自己的情绪中，没有注意到。它邀请你抬起头，睁开眼，换一个角度看世界。',
