    { area: '工作', description: '你失去了一个重要客户、被裁员，或者一个重大项目失败了，你感到深深的挫败与失落。', cardMeaning: '这张牌承认你的失落是真实的、值得被哀悼的。但请记住，你身后的杯子——你的专业技能、人脉资源、过往成就——它们还在。桥在前方，你终会找到新的方向。' },
    { area: '感情', description: '一段感情结束了，你沉浸在心碎中，反复回想曾经的美好与如今的破碎，无法自拔。', cardMeaning: '圣杯五是你此刻心境的真实写照。允许自己悲伤，但不要定义自己为"失败者"。身后站立的杯子代表你仍然拥有的爱——来自朋友、家人，以及你对自己的爱。' },
    { area: '人际关系', description: '你和一位重要的朋友发生了不可挽回的冲突，友谊破裂，你感到非常痛苦和遗憾。', cardMeaning: '这张牌告诉你，失去一段重要关系是生命中深刻的伤痛。但请留意，你身边还有其他仍然支持你的人——他们可能一直在你身后，等着你转过身来。' },
    { area: '日常生活', description: '你因为某件小事——比如搞砸了计划、丢掉了重要的东西——而陷入自责和懊恼，一整天都心情低落。', cardMeaning: '圣杯五出现在日常层面，提醒你注意情绪的"放大效应"。失去了三杯，还有两杯；搞砸了一件事，不等于搞砸了全部。试着转身，看看还有什么仍在。' },
    { area: '内在心理', description: '你感到内心有一种深刻的失落感，可能是对过去的自己、逝去的时光或未能实现的梦想的哀悼。', cardMeaning: '这张牌在内在层面邀请你正视悲伤。有些失去是必须被哀悼的，只有充分经历这个阶段，桥那头的房子——新的自我——才会真正向你敞开。' }
