      upright: '正位的星币六代表慷慨、慈善和资源的分享。你可能处于"施予者"的位置——帮助他人、捐款、分享你的财富和资源；也可能处于"接受者"的位置——接受他人的帮助、获得支持或资助。这张牌提醒你，财富的价值在于流动和分享，而非囤积。它也暗示着因果循环——你今日给予的，终将以某种形式回到你身边。在职场中，它可能代表获得奖金、加薪或投资回报。',
